    traces = []
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r-dr, c-dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                run = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr; cc += dc
                if len(run) >= 2:
                    traces.append((dr, dc, color, run))
    if not any(len(run) >= 3 for _, _, _, run in traces):
        return out
    for dr, dc, color, run in traces:
